∀ {R : Type u_1} {A : Type u_2} [inst : Semiring.{u_1} R] [inst_1 : StarRing.{u_1} R]
  [inst_2 : NonUnitalSemiring.{u_2} A] [inst_3 : StarRing.{u_2} A] [inst_4 : Module.{u_1, u_2} R A]
  [StarModule.{u_1, u_2} R A] [IsScalarTower.{u_1, u_2, u_2} R A A] [SMulCommClass.{u_1, u_2, u_2} R A A] {r : R},
  Membership.mem.{u_1, u_1}
      (AddSubmonoid.closure.{u_1} (Set.range.{u_1, u_1 + 1} fun s => HMul.hMul.{u_1, u_1, u_1} (Star.star.{u_1} s) s))
      r →
    ∀ {a : A},
      Membership.mem.{u_2, u_2}
          (AddSubmonoid.closure.{u_2}
            (Set.range.{u_2, u_2 + 1} fun s => HMul.hMul.{u_2, u_2, u_2} (Star.star.{u_2} s) s))
          a →
        Membership.mem.{u_2, u_2}
          (AddSubmonoid.closure.{u_2}
            (Set.range.{u_2, u_2 + 1} fun s => HMul.hMul.{u_2, u_2, u_2} (Star.star.{u_2} s) s))
          (HSMul.hSMul.{u_1, u_2, u_2} r a)
